tool_info.command_line:
uv run python3 -c "
from mcp.server.fastmcp import FastMCP
import json

mcp = FastMCP('test', json_response=True)

@mcp.tool(meta={'ui': {'resourceUri': 'ui://test/app'}})
def my_tool() -> str:
    return json.dumps({'hello': 'world'})

tools = mcp._tool_manager.list_tools()
for t in tools:
    print('Tool name:', t.name)
    print('Tool meta:', t.meta)
    print('Full dict:', json.dumps(t.model_dump(exclude_none=True), indent=2))
"
